// 模拟 CGLIB：子类重写可织入；final 方法无法被重写 → 无法织入通知
class FinalTarget {
    public final String sealed() { return "sealed (cannot be advised)"; }
    public String open() { return "open (can be advised)"; }
}
class FinalTarget_Enhancer extends FinalTarget {
    private Runnable advice;
    FinalTarget_Enhancer(Runnable r) { advice = r; }
    // sealed() 是 final，无法在此重写，因此不会有通知
    @Override public String open() { advice.run(); String r = super.open(); advice.run(); return r; }
}
public class Main {
    public static void main(String[] a) {
        Runnable adv = () -> System.out.println("  [advice]");
        FinalTarget proxy = new FinalTarget_Enhancer(adv);
        System.out.println("open():");
        System.out.println("  " + proxy.open());
        System.out.println("sealed():");
        System.out.println("  " + proxy.sealed());
    }
}
